--
-- Name: enforce_product_codes_verified_only_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_product_codes_verified_only_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  actor_level int := public.current_user_hierarchy_level();
BEGIN
  IF auth.role() = 'service_role' THEN
    RETURN NEW;
  END IF;

  IF actor_level >= 80 THEN
    RETURN NEW;
  END IF;

  IF actor_level >= 50
     AND (to_jsonb(NEW) - 'verified') IS NOT DISTINCT FROM (to_jsonb(OLD) - 'verified') THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'QA users can only update product_codes.verified'
    USING ERRCODE = '42501';
END;
$$;


--
-- Name: get_app_access_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_app_access_counts() RETURNS TABLE(app text, users_with_access bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'Authentication required'
        USING ERRCODE = '42501';
    END IF;

    IF NOT public.user_has_permission('access', 'manage_users', NULL) THEN
      RAISE EXCEPTION 'Manage Users access is required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  WITH granted AS (
    SELECT ur.user_id, rp.permission_id
    FROM public.user_roles ur
    JOIN public.role_permissions rp ON rp.role_id = ur.role_id

    UNION

    SELECT up.user_id, up.permission_id
    FROM public.user_permissions up
    WHERE up.granted = true
  ),
  effective AS (
    SELECT g.user_id, p.app, p.action
    FROM granted g
    JOIN public.permissions p ON p.id = g.permission_id
    JOIN auth.users u ON u.id = g.user_id
    WHERE u.deleted_at IS NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.user_permissions up2
        WHERE up2.user_id = g.user_id
          AND up2.permission_id = g.permission_id
          AND up2.granted = false
      )
  )
  SELECT e.app, count(DISTINCT e.user_id)::bigint AS users_with_access
  FROM effective e
  WHERE e.action = 'view'
     OR (
       e.app = 'access'
       AND NOT EXISTS (
         SELECT 1
         FROM public.permissions access_view
         WHERE access_view.app = 'access'
           AND access_view.action = 'view'
       )
     )
  GROUP BY e.app;
END;
$$;


