--
-- Name: get_user_permissions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_permissions(p_user_id uuid) RETURNS TABLE(app text, action text, resource text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'Authentication required'
        USING ERRCODE = '42501';
    END IF;

    IF p_user_id IS DISTINCT FROM auth.uid()
       AND public.current_user_hierarchy_level() < 80 THEN
      RAISE EXCEPTION 'Not allowed to inspect permissions for another user'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN QUERY
  SELECT DISTINCT p.app, p.action, p.resource
  FROM (
    SELECT rp.permission_id
    FROM public.user_roles ur
    JOIN public.role_permissions rp ON rp.role_id = ur.role_id
    WHERE ur.user_id = p_user_id

    UNION

    SELECT up.permission_id
    FROM public.user_permissions up
    WHERE up.user_id = p_user_id AND up.granted = true
  ) granted
  JOIN public.permissions p ON p.id = granted.permission_id
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.user_permissions up2
    WHERE up2.user_id = p_user_id
      AND up2.permission_id = granted.permission_id
      AND up2.granted = false
  );
END;
$$;


--
-- Name: log_audit_event(text, text, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_audit_event(p_action text, p_resource_type text, p_resource_id uuid DEFAULT NULL::uuid, p_new_data jsonb DEFAULT NULL::jsonb, p_old_data jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  actor_id uuid := auth.uid();
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'log_audit_event requires an authenticated actor (auth.uid() is null)'
      USING ERRCODE = '42501';
  END IF;

  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    -- Only staff who can already change access may write audit entries, so this
    -- cannot be used to forge history from a low-privilege session.
    IF public.current_user_hierarchy_level() < 80 THEN
      RAISE EXCEPTION 'Admin access is required to record audit events'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  IF p_action IS NULL OR p_resource_type IS NULL THEN
    RAISE EXCEPTION 'action and resource_type are required'
      USING ERRCODE = '22004';
  END IF;

  INSERT INTO public.audit_logs (
    action, resource_type, resource_id, old_data, new_data, user_id, user_email
  ) VALUES (
    p_action,
    p_resource_type,
    p_resource_id,
    p_old_data,
    p_new_data,
    actor_id,
    COALESCE((SELECT email FROM auth.users WHERE id = actor_id), 'system')
  );
END;
$$;


--
-- Name: log_permission_override_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_permission_override_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  known_actor uuid := auth.uid();
  subject_id uuid := COALESCE(NEW.user_id, OLD.user_id);
  granted_by_id uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.granted_by ELSE NEW.granted_by END;
  actor_id uuid := COALESCE(known_actor, granted_by_id, subject_id);
BEGIN
  INSERT INTO public.audit_logs (
    action, resource_type, resource_id, old_data, new_data, user_id, user_email
  ) VALUES (
    CASE TG_OP
      WHEN 'INSERT' THEN 'create'
      WHEN 'UPDATE' THEN 'update'
      ELSE 'delete'
    END,
    'user_permission',
    subject_id,
    CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END,
    CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END,
    actor_id,
    COALESCE((SELECT email FROM auth.users WHERE id = known_actor), 'system')
  );

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: log_role_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_role_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  known_actor uuid := auth.uid();
  actor_id uuid;
  actor_email text;
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- OLD.assigned_by is whoever granted the role, not whoever is removing it,
    -- so it is only a fallback for attribution of last resort.
    actor_id := COALESCE(known_actor, OLD.assigned_by, OLD.user_id);
    actor_email := COALESCE(
      (SELECT email FROM auth.users WHERE id = known_actor),
      'system'
    );

    INSERT INTO public.audit_logs (
      action, resource_type, resource_id, old_data, new_data, user_id, user_email
    ) VALUES (
      'delete', 'user_role', OLD.user_id, to_jsonb(OLD), NULL,
      actor_id, actor_email
    );

    RETURN OLD;
  END IF;

  actor_id := COALESCE(NEW.assigned_by, known_actor, NEW.user_id);
  actor_email := COALESCE(
    (SELECT email FROM auth.users WHERE id = actor_id),
    (SELECT email FROM auth.users WHERE id = NEW.user_id),
    'system'
  );

  INSERT INTO public.audit_logs (
    action, resource_type, resource_id, old_data, new_data, user_id, user_email
  ) VALUES (
    CASE WHEN TG_OP = 'INSERT' THEN 'create' ELSE 'update' END,
    'user_role',
    NEW.user_id,
    CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) ELSE NULL END,
    to_jsonb(NEW),
    actor_id,
    actor_email
  );

  RETURN NEW;
END;
$$;


