--
-- Name: rhino_lock_down_new_functions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rhino_lock_down_new_functions() RETURNS event_trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  obj record;
BEGIN
  FOR obj IN
    SELECT object_identity
    FROM pg_catalog.pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE FUNCTION', 'CREATE PROCEDURE')
      AND schema_name = 'public'
      AND object_identity <> 'public.normalize_brand_name(text)'
  LOOP
    EXECUTE pg_catalog.format('REVOKE EXECUTE ON ROUTINE %s FROM PUBLIC, anon', obj.object_identity);
  END LOOP;
END;
$$;


