-- Name: FUNCTION rhino_lock_down_new_functions(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rhino_lock_down_new_functions() IS 'Event trigger: revokes PUBLIC/anon EXECUTE on every function created in public. See migration 013.';


--
-- Name: search_audit_logs(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_audit_logs(p_query text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id text, action text, resource_type text, resource_id text, old_data jsonb, new_data jsonb, user_id text, user_email text, created_at timestamp with time zone, total_count bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_limit int := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200);
  v_offset int := GREATEST(COALESCE(p_offset, 0), 0);
  v_query text := NULLIF(btrim(COALESCE(p_query, '')), '');
  v_pattern text;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    IF auth.uid() IS NULL THEN
      RAISE EXCEPTION 'Authentication required'
        USING ERRCODE = '42501';
    END IF;

    IF NOT public.user_has_permission('access', 'view_audit_logs', NULL) THEN
      RAISE EXCEPTION 'View Audit Logs access is required'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- Neutralise LIKE wildcards in user input so a search for "%" does not match
  -- everything and "_" stays a literal underscore (resource_type values such as
  -- user_role contain them).
  IF v_query IS NOT NULL THEN
    v_pattern := '%' || replace(replace(replace(v_query, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  END IF;

  RETURN QUERY
  WITH filtered AS (
    SELECT a.*
    FROM public.audit_logs a
    WHERE v_pattern IS NULL
       OR a.action ILIKE v_pattern ESCAPE '\'
       OR a.resource_type ILIKE v_pattern ESCAPE '\'
       OR a.resource_id::text ILIKE v_pattern ESCAPE '\'
       OR COALESCE(a.user_email, '') ILIKE v_pattern ESCAPE '\'
  )
  SELECT
    f.id::text,
    f.action::text,
    f.resource_type::text,
    f.resource_id::text,
    f.old_data::jsonb,
    f.new_data::jsonb,
    f.user_id::text,
    f.user_email::text,
    f.created_at::timestamptz,
    COUNT(*) OVER ()::bigint AS total_count
  FROM filtered f
  ORDER BY f.created_at DESC, f.id DESC
  LIMIT v_limit OFFSET v_offset;
END;
$$;


--
-- Name: set_product_brands(uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_product_brands(p_product_id uuid, p_primary_brand_id uuid, p_additional_brand_ids uuid[] DEFAULT ARRAY[]::uuid[]) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  desired_brand_ids uuid[];
begin
  desired_brand_ids := array(
    select distinct brand_id
    from unnest(
      case
        when p_primary_brand_id is null then coalesce(p_additional_brand_ids, array[]::uuid[])
        else array_append(coalesce(p_additional_brand_ids, array[]::uuid[]), p_primary_brand_id)
      end
    ) as brand_id
    where brand_id is not null
  );

  delete from public.product_brands
  where product_id = p_product_id
    and not (brand_id = any(coalesce(desired_brand_ids, array[]::uuid[])));

  insert into public.product_brands (product_id, brand_id)
  select p_product_id, brand_id
  from unnest(coalesce(desired_brand_ids, array[]::uuid[])) as brand_id
  on conflict do nothing;

  update public.products
  set primary_brand_id = p_primary_brand_id
  where id = p_product_id;
end;
$$;


