--
-- Name: user_has_permission(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_has_permission(p_app text, p_action text, p_resource text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    JOIN public.role_permissions rp ON rp.role_id = ur.role_id
    JOIN public.permissions p ON p.id = rp.permission_id
    WHERE ur.user_id = auth.uid()
      AND p.app = p_app
      AND p.action = p_action
      AND p.resource IS NOT DISTINCT FROM p_resource

    UNION ALL

    SELECT 1
    FROM public.user_permissions up
    JOIN public.permissions p ON p.id = up.permission_id
    WHERE up.user_id = auth.uid()
      AND up.granted = true
      AND p.app = p_app
      AND p.action = p_action
      AND p.resource IS NOT DISTINCT FROM p_resource
  )
  AND NOT EXISTS (
    SELECT 1
    FROM public.user_permissions up
    JOIN public.permissions p ON p.id = up.permission_id
    WHERE up.user_id = auth.uid()
      AND up.granted = false
      AND p.app = p_app
      AND p.action = p_action
      AND p.resource IS NOT DISTINCT FROM p_resource
  );
$$;


--
-- Name: user_hierarchy_level(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_hierarchy_level(p_user_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT r.hierarchy_level
     FROM user_roles ur
     JOIN roles r ON r.id = ur.role_id
     WHERE ur.user_id = p_user_id),
    0
  );
$$;


